using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class Confucius
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "At fifteen my heart was set on learning; at thirty I stood firm; at forty I had no more doubts; at fifty I knew the will of heaven; at sixty my ear was obedient; at seventy I could follow my heart's desire without overstepping the boundaries of what was right.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The Superior Man is all-embracing and not partial. The inferior man is partial and not all-embracing.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "If you see what is right and fail to act on it, you lack courage.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Men do not stumble over mountains, but over molehills.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Man has three ways of acting wisely. First, on meditation; that is the noblest. Secondly, on imitation; that is the easiest. Thirdly, on experience; that is the bitterest.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "By three methods we may learn wisdom: First, by reflection, which is the noblest; Second, by imitation, which is the easiest; and third by experience, which is the bitterest.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "It is not truth that makes man great, but man that makes truth great.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "It is more shameful to distrust our friends than to be deceived by them.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The more man meditates upon good thoughts, the better will be his world and the world at large.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Isn't it a pleasure to study and practice what you have learned? Isn't it also great when friends visit from distant places? If one remains not annoyed when he is not understood by people around him, isn't he a sage?", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Fine words and an insinuating appearance are seldom associated with true virtue.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "A young man should serve his parents at home and be respectful to elders outside his home. He should be earnest and truthful, loving all, but become intimate with humaneness. After doing this, if he has energy to spare, he can study literature and the arts.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Be loyal and trustworthy. Do not befriend anyone who is lower than yourself in this regard. When making a mistake, do not be afraid to correct it.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "When the Superior Man (Junzi) eats he does not try to stuff himself; at rest he does not seek perfect comfort; he is diligent in his work and careful in speech. He avails himself to people of the Tao and thereby corrects himself. This is the kind of person of whom you can say, 'he loves learning.'", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "He who exercises government by means of his virtue may be compared to the north polar star, which keeps its place and all the stars turn towards it.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Reviewing what you have learned and learning anew, you are fit to be a teacher.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "To study and not think is a waste. To think and not study is dangerous.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Learning without thought is labor lost; thought without learning is perilous.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "You [a disciple], shall I teach you about knowledge? What you know, you know, what you don't know, you don't know. This is true knowledge.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "To know what you know and what you do not know, that is true knowledge.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "See a person's means (of getting things). Observe his motives. Examine that in which he rests. How can a person conceal his character?", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "To worship to other than one's own ancestral spirits is brown-nosing. If you see what is right and fail to act on it, you lack courage.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "To see what is right, and not to do it, is want of courage or of principle.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "If a man has no humaneness what can his propriety be like? If a man has no humaneness what can his happiness be like?", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The Yin based its propriety on that of the Xia, and what it added and subtracted is knowable. The Zhou has based its propriety on that of the Shang and what it added and subtracted is knowable. In this way, what continues from the Chou, even if 100 generations hence, is knowable.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Being in humaneness is good. If we select other goodness and thus are far apart from humaneness, how can we be the wise?", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "When we see men of worth, we should think of equaling them; when we see men of a contrary character, we should turn inwards and examine ourselves.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "When you meet someone better than yourself, turn your thoughts to becoming his equal. When you meet someone not as good as you are, look within and examine your own self.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "When you see a good person, think of becoming like her/him. When you see someone not so good, reflect on your own weak points.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The cautious seldom err.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The superior man is modest in his speech, but exceeds in his actions.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Virtue (or the man of virtue) is not left to stand alone. He who practices it will have neighbors.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The superior man thinks of virtue; the small man thinks of comfort. The superior man thinks of the sanctions of law; the small man thinks of favors which he may receive.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The Superior Man is aware of Righteousness, the inferior man is aware of advantage.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The virtuous man is driven by responsibility, the non-virtuous man is driven by profit.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The superior man understands what is right; the inferior man understands what will sell.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Chi Wan thought thrice, and then acted. When the Master was informed of it, he said, \"Twice may do.\"", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "They who know the truth are not equal to those who love it, and those who love it are not equal to those who delight in it.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "To those whose talents are above mediocrity, the highest subjects may be announced. To those who are below mediocrity, the highest subjects may not be announced.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The wise find pleasure in water; the virtuous find pleasure in hills. The wise are active; the virtuous are tranquil. The wise are joyful; the virtuous are long-lived.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "To give one's self earnestly to the duties due to men, and, while respecting spiritual beings, to keep aloof from them, may be called wisdom.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The man of virtue makes the difficulty to be overcome his first business, and success only a subsequent consideration: this may be called perfect virtue.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "To rank the effort above the prize may be called love.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "I do not open up the truth to one who is not eager to get knowledge, nor help out any one who is not anxious to explain himself. When I have presented one corner of a subject to any one, and he cannot from it learn the other three, I do not repeat my lesson.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "When I walk along with two others, they may serve me as my teachers. I will select their good qualities and follow them, their bad qualities and avoid them.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The superior man is satisfied and composed; the mean man is always full of distress.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The virtuous is frank and open; the non-virtuous is secretive and worrying.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Leaving virtue without proper cultivation; not thoroughly discussing what is learned; not being able to move towards righteousness of which a knowledge is gained; and not being able to change what is not good: - these are the things which occasion me solicitude.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The silent treasuring up of knowledge; learning without satiety; and instructing others without being wearied: which one of these things belongs to me?", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "When a country is well governed, poverty and a mean condition are things to be ashamed of. When a country is ill governed, riches and honor are things to be ashamed of.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "To be wealthy and honored in an unjust society is a disgrace.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "A man's character is formed by the Odes, developed by the Rites and perfected by music.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The man of perfect virtue is cautious and slow in his speech. When a man feels the difficulty of doing, can he be other than cautious and slow in speaking?", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The superior man has neither anxiety nor fear. When internal examination discovers nothing wrong, what is there to be anxious about, what is there to fear?", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Let the superior man never fail reverentially to order his own conduct, and let him be respectful to others and observant of propriety:-then all within the four seas, all men are brothers. What has the superior man to do with being distressed because he has no brothers?", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "If the people have no faith in their rulers, there is no standing for the state.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "By extensively studying all learning, and keeping himself under the restraint of the rules of propriety, one may thus likewise not err from what is right.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "If names be not correct, language is not in accordance with the truth of things.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The beginning of wisdom is to call things by their proper name.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "There are only the wise of the highest class, and the stupid of the lowest class, who cannot be changed.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "There is the love of knowing without the love of learning; the beclouding here leads to dissipation of mind.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The Master said, \"Hard is it to deal with him, who will stuff himself with food the whole day, without applying his mind to anything good! Are there not gamesters and chess players? To be one of these would still be better than doing nothing at all.\"", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Of all people, girls and servants are the most difficult to behave to. If you are familiar with them, they lose their humility. If you maintain a reserve towards them, they are discontented.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "When a man at forty is the object of dislike, he will always continue what he is.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The superior man, when resting in safety, does not forget that danger may come. When in a state of security he does not forget the possibility of ruin. When all is orderly, he does not forget that disorder may come. Thus his person is not endangered, and his States and all their clans are preserved.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "What you do not want done to yourself, do not do to others.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Recompense hatred with justice, and recompense kindness with kindness.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "A man living without conflict is as if he never lived at all.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "A scholar who loves comfort is not worthy of the name.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The man of virtue makes the difficulty to be overcome his first business, and success only a subsequent consideration.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "When you have faults, do not fear to abandon them.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Guide the people by law, subdue them by punishment; they may shun crime, but will be void of shame. Guide them by example, subdue them by courtesy; they will learn shame, and come to be good.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Only after Winter comes do we know that the pine and the cypress are the last to fade.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The superior man loves his soul; the inferior man loves his property.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Things have their root and their branches. Affairs have their end and their beginning. To know what is first and what is last will lead near to what is taught in the Great Learning.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "From the Son of Heaven down to the mass of the people, all must consider the cultivation of the person the root of everything besides.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "What Heaven has conferred is called The Nature; an accordance with this nature is called The Path of duty; the regulation of this path is called Instruction. The path may not be left for an instant. If it could be left, it would not be the path.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "There is nothing more visible than what is secret, and nothing more manifest than what is minute. Therefore the superior man is watchful over himself, when he is alone.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Let the states of equilibrium and harmony exist in perfection, and a happy order will prevail throughout heaven and earth, and all things will be nourished and flourish.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Perfect is the virtue which is according to the Mean! Rare have they long been among the people, who could practice it!", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "I know how it is that the path of the Mean is not walked in - The knowing go beyond it, and the stupid do not come up to it. I know how it is that the path of the Mean is not understood - The men of talents and virtue go beyond it, and the worthless do not come up to it.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "There is no body but eats and drinks. But they are few who can distinguish flavors.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Men all say, \"We are wise\"; but being driven forward and taken in a net, a trap, or a pitfall, they know not how to escape. Men all say, \"We are wise\"; but happening to choose the course of the Mean, they are not able to keep it for a round month.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The kingdom, its states, and its families, may be perfectly ruled; dignities and emoluments may be declined; naked weapons may be trampled under the feet; but the course of the Mean cannot be attained to.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The superior man accords with the course of the Mean. Though he may be all unknown, unregarded by the world, he feels no regret - It is only the sage who is able for this.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The way of the superior man may be found, in its simple elements, in the intercourse of common men and women; but in its utmost reaches, it shines brightly through Heaven and Earth.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The Path is not far from man. When men try to pursue a course, which is far from the common indications of consciousness, this course cannot be considered The Path.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The superior man governs men, according to their nature, with what is proper to them, and as soon as they change what is wrong, he stops.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "When one cultivates to the utmost the principles of his nature, and exercises them on the principle of reciprocity, he is not far from the path. What you do not like when done to yourself, do not do to others.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "In archery we have something like the way of the superior man. When the archer misses the center of the target, he turns round and seeks for the cause of his failure in himself.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The way of the superior man may be compared to what takes place in traveling, when to go to a distance we must first traverse the space that is near, and in ascending a height, when we must begin from the lower ground.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "How abundantly do spiritual beings display the powers that belong to them! We look for them, but do not see them; we listen to, but do not hear them; yet they enter into all things, and there is nothing without them.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Heaven, in the production of things, is sure to be bountiful to them, according to their qualities. Hence the tree that is flourishing, it nourishes, while that which is ready to fall, it overthrows.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The administration of government lies in getting proper men. Such men are to be got by means of the ruler's own character. That character is to be cultivated by his treading in the ways of duty. And the treading those ways of duty is to be cultivated by the cherishing of benevolence.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Benevolence is the characteristic element of humanity.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "To be fond of learning is to be near to knowledge. To practice with vigor is to be near to magnanimity. To possess the feeling of shame is to be near to energy.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "By the ruler's cultivation of his own character, the duties of universal obligation are set forth. By honoring men of virtue and talents, he is preserved from errors of judgment.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "It is characteristic of the most entire sincerity to be able to foreknow. When a nation or family is about to flourish, there are sure to be happy omens; and when it is about to perish, there are sure to be unlucky omens.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Sincerity is that whereby self-completion is effected, and its way is that by which man must direct himself.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Sincerity is the end and beginning of things; without sincerity there would be nothing. On this account, the superior man regards the attainment of sincerity as the most excellent thing.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The way of Heaven and Earth may be completely declared in one sentence: They are without any doubleness, and so they produce things in a manner that is unfathomable.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "To no one but the Son of Heaven does it belong to order ceremonies, to fix the measures, and to determine the written characters.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "His presenting himself with his institutions before spiritual beings, without any doubts arising about them, shows that he knows Heaven. His being prepared, without any misgivings, to wait for the rise of a sage a hundred ages after, shows that he knows men.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The superior man examines his heart, that there may be nothing wrong there, and that he may have no cause for dissatisfaction with himself. That wherein the superior man cannot be equaled is simply this - his work which other men cannot see.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "The superior man, even when he is not moving, has a feeling of reverence, and while he speaks not, he has the feeling of truthfulness.", Author = "Confucius" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Confucius", Text = "Among the appliances to transform the people, sound and appearances are but trivial influences.", Author = "Confucius" },
        };
    }
}
